python3 -c "
import json
with open('/tmp/migration_notes.json') as f:
    data = json.load(f)
notes = data['notes']
by_kb = {}
for n in notes:
    kb = n['kb']
    if kb not in by_kb:
        by_kb[kb] = []
    by_kb[kb].append(n)

for kb, ns in by_kb.items():
    print(f'{kb}: {len(ns)} notes')
    for n in ns[:3]:
        print(f'  - {n[\"title\"][:60]} (id={n[\"note_id\"]})')
    if len(ns) > 3:
        print(f'  ... and {len(ns)-3} more')
"
